INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist das Kommentieren des Quellcodes in TDD notwendig, um den Entwicklungsprozess nachzuvollziehen?', 2, '[{"text": "Nein", "correct": true, "because": "Tests sind Haupt-Dokumentation"}, {"text": "Ja", "correct": false, "because": "Kommentare ergänzen nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Können gut geschriebene Tests in TDD die Notwendigkeit von Quellcode-Kommentaren reduzieren?', 2, '[{"text": "Ja", "correct": true, "because": "Tests erklären Verhalten"}, {"text": "Nein", "correct": false, "because": "Tests sind selbsterklärend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Quellcode-Kommentare in TDD immer technische Details der Implementierung enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Absicht, nicht Details"}, {"text": "Ja", "correct": false, "because": "Details oft redundant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Kommentieren des Quellcodes in TDD die Wartbarkeit der Software verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Kommentare erleichtern Verständnis"}, {"text": "Nein", "correct": false, "because": "Wartbarkeit wird unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Quellcode-Kommentare in TDD nur für komplexe Projekte sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Breite Anwendbarkeit"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Kommentieren des Quellcodes in TDD?', 2, '[{"text": "Ergänzung der Test-Dokumentation", "correct": true, "because": "Kommentare erklären Absicht"}, {"text": "Ersetzung der Tests", "correct": false, "because": "Tests zentral"}, {"text": "Optimierung der Laufzeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Kommentaren ist in TDD am nützlichsten?', 3, '[{"text": "Kommentare zur Absicht", "correct": true, "because": "Erklären Warum, nicht Wie"}, {"text": "Technische Implementierungsdetails", "correct": false, "because": "Oft redundant"}, {"text": "Zeitstempel", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich aus gutem Quellcode-Kommentieren in TDD?', 2, '[{"text": "Verbessertes Verständnis", "correct": true, "because": "Erleichtert Nachvollziehbarkeit"}, {"text": "Schnellere Testausführung", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Testaufwand", "correct": false, "because": "Tests bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt des Quellcode-Kommentierens unterstützt die Teamarbeit in TDD?', 2, '[{"text": "Klarheit über Code-Absicht", "correct": true, "because": "Fördert Kommunikation"}, {"text": "Hohe Komplexität", "correct": false, "because": "Hinderlich"}, {"text": "Technische Details", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip von TDD wird durch Quellcode-Kommentare ergänzt?', 2, '[{"text": "Selbsterklärender Code", "correct": true, "because": "Kommentare unterstützen"}, {"text": "Maximale Abdeckung", "correct": false, "because": "Testziel"}, {"text": "Schnelle Iterationen", "correct": false, "because": "Nicht primär"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Kommentaren sind in TDD sinnvoll?', 4, '[{"text": "Absichtserklärungen", "correct": true, "because": "Erklären Warum"}, {"text": "API-Dokumentation", "correct": true, "because": "Schnittstellen klar"}, {"text": "Implementierungsdetails", "correct": false, "because": "Oft redundant"}, {"text": "Kontextinformationen", "correct": true, "because": "Fördert Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Kommentieren des Quellcodes in TDD?', 3, '[{"text": "Besseres Verständnis", "correct": true, "because": "Klarheit für Team"}, {"text": "Einfachere Wartung", "correct": true, "because": "Änderungen erleichtert"}, {"text": "Schnellere Tests", "correct": false, "because": "Nicht primär"}, {"text": "Teamkommunikation", "correct": true, "because": "Fördert Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es beim Quellcode-Kommentieren in TDD?', 3, '[{"text": "Synchronisation mit Code", "correct": true, "because": "Änderungen müssen passen"}, {"text": "Zeitaufwand", "correct": true, "because": "Erstellung kostet Zeit"}, {"text": "Keine Testunterstützung", "correct": false, "because": "Tests zentral"}, {"text": "Überflüssigkeit durch Tests", "correct": true, "because": "Tests erklären oft genug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Best Practices sollten beim Kommentieren des Quellcodes in TDD beachtet werden?', 4, '[{"text": "Fokus auf Absicht", "correct": true, "because": "Warum statt Wie"}, {"text": "Vermeidung von Redundanz", "correct": true, "because": "Tests erklären Details"}, {"text": "Detaillierte technische Beschreibungen", "correct": false, "because": "Oft überflüssig"}, {"text": "Kürze und Prägnanz", "correct": true, "because": "Klarheit ohne Überladung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte verbessert das Kommentieren des Quellcodes in TDD?', 3, '[{"text": "Code-Verständnis", "correct": true, "because": "Klarheit für Entwickler"}, {"text": "Wartbarkeit", "correct": true, "because": "Änderungen erleichtert"}, {"text": "Testausführung", "correct": false, "because": "Nicht primär"}, {"text": "Teamzusammenarbeit", "correct": true, "because": "Kommunikation gefördert"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Quellcode-Kommentare in TDD sind immer überflüssig wegen Tests. b) Kommentare können die Wartbarkeit verbessern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Kommentare nicht überflüssig, helfen"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kommentare in TDD sollten die Absicht erklären. b) Tests machen Kommentare vollständig überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Absicht wichtig, Kommentare ergänzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Quellcode-Kommentare in TDD sind nur für große Projekte nötig. b) Kommentare unterstützen die Teamkommunikation.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Größe egal, Kommunikation gefördert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kommentare in TDD sollten technische Details vermeiden. b) Kommentare erhöhen die Testzeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Details redundant, Zeit unbeeinflusst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Quellcode-Kommentare in TDD verbessern das Verständnis. b) Kommentare sind in TDD immer Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verständnis ja, Pflicht nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

